"""F08's generated audio (``06`` §5), stdlib only (``wave``-style PCM, ``random`` with fixed
seeds), and the example game's music and effect:

    .venv/Scripts/python tests/fixtures/F08/make_audio.py            # game/audio/
    .venv/Scripts/python tests/fixtures/F08/make_audio.py <folder>   # <folder>/audio/

Everything here is generated, so it is original and CC0. The tests build their files at test
time in ``tmp_path`` (nothing large is committed): tones (``06`` §5.2 ``formats/``), seeded noise
(``loops/``), a constant (``dc_4s.wav``), WAVs whose header declares more than they hold
(``broken/`` truncations), and FLAC. There is no Ogg Vorbis, Opus, or MP3 encoder in the
standard library, so those rows use pygame-ce's own example files (``house_lo.*``, shipped
with pygame-ce under its license) or wait for the pinned-encoder fixtures of F08 step 12.

Voice lines (``voice_wav``) are 600 Hz tones, as Template A's voices (``06`` §5.1).
``broken_files`` builds AC-F08-35's ``broken/`` rows: content that is not what its extension
says, from pygame-ce's ``MIDI_sample.mid``, ``surfonasinewave.xm``, and ``house_lo.ogg``/
``.opus`` (read from the installed package, not copied) and generated bytes.

FLAC is written with VERBATIM subframes (no compression, valid per the FLAC format), so a
decoder must reproduce the PCM exactly.

``EXAMPLE`` lists the example game's files; ``example_music`` is a gentle 8-second pentatonic
loop (22,050 Hz mono, 16-bit), rendered into a circular buffer so its end flows into its start
with no click, and ``example_chime`` a short bell for ``play sound``. Step 12 (PR-F08-33) adds
``example_bridge_music`` (the music change and the queue), ``example_river`` (looping
ambience), ``example_firework`` (a one-shot over it), and ``example_voice`` lines (murmured,
speech-like syllables, not words) for three lines of the festival, plus ``audio/LICENSES.txt``,
the license record of every file (``license_record``). The example stays WAV because there is
no Ogg encoder here; WAV loops without a gap too. F06 step 3 adds ``example_blip``: Hana's
bright and Daichi's low text blip (``blips/``), each well under 0.5 s.
"""

import functools
import importlib.util
import math
import random
import struct
import sys
from pathlib import Path

GAME = Path(__file__).resolve().parents[3] / "game"
FULL = 32_767


# --- PCM -------------------------------------------------------------------------------------

def _pack(samples: list[int]) -> bytes:
    return struct.pack(f"<{len(samples)}h", *samples)


def pcm_tone(seconds: float, *, freq: float = 1000.0, rate: int = 48_000, channels: int = 2,
             amplitude: int = 16_384) -> bytes:
    """A sine (``amplitude`` 16,384 is −6 dBFS), interleaved signed 16-bit."""
    frames = round(seconds * rate)
    step = 2 * math.pi * freq / rate
    out = []
    for i in range(frames):
        value = round(amplitude * math.sin(step * i))
        out.extend((value,) * channels)
    return _pack(out)


def pcm_noise(seconds: float, *, seed: int, rate: int = 48_000, channels: int = 2,
              amplitude: int = 12_000) -> bytes:
    """Seeded white noise, never exactly zero (so a stretch of zeros is a real gap)."""
    rng = random.Random(seed)
    frames = round(seconds * rate)
    out = []
    for _ in range(frames * channels):
        value = rng.randint(-amplitude, amplitude)
        out.append(value if value != 0 else 1)
    return _pack(out)


def pcm_dc(seconds: float, *, value: int = 20_000, rate: int = 48_000,
           channels: int = 2) -> bytes:
    return _pack([value] * (round(seconds * rate) * channels))


# --- Containers --------------------------------------------------------------------------------

def wav(pcm: bytes, *, rate: int = 48_000, channels: int = 2,
        declared_bytes: int | None = None) -> bytes:
    """A 16-bit PCM WAV of ``pcm``; ``declared_bytes`` overrides the ``data`` size (a file cut
    short declares more than it holds)."""
    fmt = struct.pack("<HHIIHH", 1, channels, rate, rate * channels * 2, channels * 2, 16)
    size = len(pcm) if declared_bytes is None else declared_bytes
    body = b"WAVE" + b"fmt " + struct.pack("<I", len(fmt)) + fmt + b"data" + struct.pack(
        "<I", size) + pcm
    return b"RIFF" + struct.pack("<I", len(body)) + body


def tone_wav(seconds: float = 2.0, *, rate: int = 48_000, channels: int = 2,
             freq: float = 1000.0) -> bytes:
    return wav(pcm_tone(seconds, freq=freq, rate=rate, channels=channels), rate=rate,
               channels=channels)


def noise_wav(seconds: float, *, seed: int, rate: int = 48_000, channels: int = 2) -> bytes:
    return wav(pcm_noise(seconds, seed=seed, rate=rate, channels=channels), rate=rate,
               channels=channels)


def voice_wav(seconds: float = 1.5, *, freq: float = 600.0) -> bytes:
    """A voice-line stand-in: a 600 Hz tone at −6 dBFS, 48,000 Hz stereo."""
    return tone_wav(seconds, freq=freq)


def dc_wav(seconds: float = 4.0, *, value: int = 20_000) -> bytes:
    return wav(pcm_dc(seconds, value=value))


def truncated_wav(declared: float, actual: float, *, seed: int = 9) -> bytes:
    """Noise whose header declares ``declared`` seconds but which holds ``actual``."""
    pcm = pcm_noise(actual, seed=seed)
    return wav(pcm, declared_bytes=round(declared * 48_000) * 4)


# --- FLAC (VERBATIM subframes) -----------------------------------------------------------------

_FLAC_BLOCK = 4_096
_FLAC_RATE_CODES = {22_050: 0b0100, 44_100: 0b1001, 48_000: 0b1010}


def _crc8(data: bytes) -> int:
    crc = 0
    for byte in data:
        crc ^= byte
        for _ in range(8):
            crc = ((crc << 1) ^ 0x07) & 0xFF if crc & 0x80 else (crc << 1) & 0xFF
    return crc


def _crc16(data: bytes) -> int:
    crc = 0
    for byte in data:
        crc ^= byte << 8
        for _ in range(8):
            crc = ((crc << 1) ^ 0x8005) & 0xFFFF if crc & 0x8000 else (crc << 1) & 0xFFFF
    return crc


def _utf8_number(n: int) -> bytes:
    if n < 0x80:
        return bytes([n])
    if n < 0x800:
        return bytes([0xC0 | (n >> 6), 0x80 | (n & 0x3F)])
    return bytes([0xE0 | (n >> 12), 0x80 | ((n >> 6) & 0x3F), 0x80 | (n & 0x3F)])


def flac(pcm: bytes, *, rate: int, channels: int) -> bytes:
    """A FLAC file of 16-bit ``pcm`` (``rate`` in ``_FLAC_RATE_CODES``, 1 or 2 channels)."""
    samples = struct.unpack(f"<{len(pcm) // 2}h", pcm)
    frames = len(samples) // channels
    info = (struct.pack(">HH", _FLAC_BLOCK, _FLAC_BLOCK) + b"\0\0\0" + b"\0\0\0"
            + ((rate << 44) | ((channels - 1) << 41) | (15 << 36) | frames).to_bytes(8, "big")
            + b"\0" * 16)
    out = bytearray(b"fLaC" + bytes([0x80, 0, 0, len(info)]) + info)
    for number, first in enumerate(range(0, frames, _FLAC_BLOCK)):
        count = min(_FLAC_BLOCK, frames - first)
        size_code = 0b1100 if count == _FLAC_BLOCK else 0b0111
        header = bytearray(b"\xff\xf8")
        header.append((size_code << 4) | _FLAC_RATE_CODES[rate])
        header.append(((channels - 1) << 4) | (0b100 << 1))      # 16 bits per sample
        header += _utf8_number(number)
        if size_code == 0b0111:
            header += struct.pack(">H", count - 1)
        header.append(_crc8(bytes(header)))
        body = bytearray()
        for channel in range(channels):
            body.append(0x02)                                    # VERBATIM, no wasted bits
            body += struct.pack(f">{count}h", *samples[first * channels + channel:
                                                       (first + count) * channels:channels])
        frame = bytes(header) + bytes(body)
        out += frame + struct.pack(">H", _crc16(frame))
    return bytes(out)


# --- broken/ (AC-F08-35) ---------------------------------------------------------------------

def pygame_data(name: str) -> bytes:
    """A file of pygame-ce's ``examples/data`` (shipped with pygame-ce, under its license)."""
    spec = importlib.util.find_spec("pygame")
    assert spec is not None and spec.origin is not None
    return (Path(spec.origin).parent / "examples" / "data" / name).read_bytes()


def mod_module(title: bytes = b"song") -> bytes:
    """A 4-channel ProTracker MOD: no magic at offset 0, ``M.K.`` at 1080, one empty
    pattern."""
    head = title.ljust(20, b"\0") + b"\0" * 30 * 31 + bytes([1, 127]) + bytes(128)
    return head + b"M.K." + b"\0" * 1024


def riff(form: bytes, chunk: bytes, body: bytes) -> bytes:
    inner = form + chunk + struct.pack("<I", len(body)) + body
    return b"RIFF" + struct.pack("<I", len(inner)) + inner


def broken_files() -> dict[str, bytes]:
    """AC-F08-35's rows (``broken/<name>`` -> content), plus I-13(f)'s Opus-in-``.ogg``."""
    midi = pygame_data("MIDI_sample.mid")
    xm = pygame_data("surfonasinewave.xm")
    return {
        "midi_as.ogg": midi, "midi_as.mp3": midi, "midi_as.wav": midi,
        "rmid.wav": riff(b"RMID", b"data", midi),
        "xm_as.wav": xm, "xm_as.ogg": xm,
        "mod_as.mp3": mod_module(),
        "wav_as.ogg": tone_wav(0.5),
        "ogg_as.wav": pygame_data("house_lo.ogg"),
        "flac_as.mp3": flac(pcm_tone(0.5, rate=48_000), rate=48_000, channels=2),
        "riff_avi.wav": riff(b"AVI ", b"LIST", b"\0" * 64),
        "empty.ogg": b"", "ogg3.ogg": b"Ogg",
        "opus_as.ogg": pygame_data("house_lo.opus"),
    }


# --- loops/ (F08 step 10): Ogg files with rewritten header pages ------------------------------
# There is no Ogg encoder here (no ffmpeg, oggenc, or opusenc; F08 step 12 pins one), so the
# loop-point fixtures are pygame-ce's own ``house_lo.ogg`` (Vorbis, 11,025 Hz mono, 78,331
# samples) and ``house_lo.opus`` (48,000 Hz mono, 341,036 samples after a 312-sample
# pre-skip) with only their header pages rewritten. A Vorbis decoder doesn't use the
# identification header's rate, so ``with_rate(…, 48_000)`` gives a 48,000 Hz stream that SDL
# plays without resampling (1.632 s), and ``with_rate(…, 1_087)`` a 72.06 s one. This builder
# is independent of ``engine/audio/oggloop.py`` (its own CRC and lacing).

def _crc_byte(value: int) -> int:
    crc = value << 24
    for _ in range(8):
        crc = ((crc << 1) ^ 0x04C11DB7) if crc & 0x80000000 else crc << 1
    return crc & 0xFFFFFFFF


_CRC_TABLE = [_crc_byte(value) for value in range(256)]


def _crc32_ogg(data: bytes) -> int:
    """Ogg's CRC-32 (polynomial 0x04C11DB7, not reflected, initial 0)."""
    crc = 0
    for byte in data:
        crc = ((crc << 8) & 0xFFFFFFFF) ^ _CRC_TABLE[(crc >> 24) ^ byte]
    return crc


def ogg_pages(data: bytes) -> list[tuple[bytes, bytes, bytes]]:
    """Every page as ``(27 header bytes, segment table, body)``."""
    pages, at = [], 0
    while at < len(data):
        assert data[at:at + 4] == b"OggS", at
        count = data[at + 26]
        lacing = data[at + 27:at + 27 + count]
        size = sum(lacing)
        body_at = at + 27 + count
        pages.append((data[at:at + 27], lacing, data[body_at:body_at + size]))
        at = body_at + size
    return pages


def ogg_page(fixed: bytes, lacing: bytes, body: bytes, *, sequence: int | None = None,
             flags: int | None = None) -> bytes:
    """A page from header fields with a fresh segment count and CRC."""
    head = bytearray(fixed[:27])
    if flags is not None:
        head[5] = flags
    if sequence is not None:
        head[18:22] = struct.pack("<I", sequence)
    head[22:26] = b"\0\0\0\0"
    head[26] = len(lacing)
    raw = bytes(head) + lacing + body
    return raw[:22] + struct.pack("<I", _crc32_ogg(raw)) + raw[26:]


def with_rate(ogg: bytes, rate: int) -> bytes:
    """A Vorbis file with its identification header's rate set to ``rate``."""
    fixed, lacing, body = ogg_pages(ogg)[0]
    page0 = ogg_page(fixed, lacing, body[:12] + struct.pack("<I", rate) + body[16:])
    return page0 + ogg[len(fixed) + len(lacing) + len(body):]


def _split_packets(pages: list[tuple[bytes, bytes, bytes]]) -> list[bytes]:
    packets, current = [], b""
    for _fixed, lacing, body in pages:
        at = 0
        for value in lacing:
            current += body[at:at + value]
            at += value
            if value < 255:
                packets.append(current)
                current = b""
    return packets


def _comments(packet: bytes, magic_len: int) -> list[bytes]:
    at = magic_len
    vendor = struct.unpack("<I", packet[at:at + 4])[0]
    at += 4 + vendor
    count = struct.unpack("<I", packet[at:at + 4])[0]
    at += 4
    out = []
    for _ in range(count):
        size = struct.unpack("<I", packet[at:at + 4])[0]
        out.append(packet[at + 4:at + 4 + size])
        at += 4 + size
    return out


def vorbis_comments(ogg: bytes) -> list[bytes]:
    """The user comments of a Vorbis file."""
    return _comments(_split_packets(ogg_pages(ogg)[1:])[0], 7)


def opus_comments(opus: bytes) -> list[bytes]:
    """The user comments of an Opus file."""
    return _comments(_split_packets(ogg_pages(opus)[1:])[0], 8)


def header_page_count(ogg: bytes, packets: int = 2) -> int:
    """k: the pages after page 0 that hold the next ``packets`` header packets."""
    done = 0
    for index, (_fixed, lacing, _body) in enumerate(ogg_pages(ogg)[1:], start=1):
        done += sum(1 for value in lacing if value < 255)
        if done >= packets:
            return index
    raise AssertionError("no header")


def with_comments(ogg: bytes, comments: list[bytes], *, comment_alone: bool = False) -> bytes:
    """A Vorbis file whose comment header holds ``comments`` (the vendor kept), laced into
    as many pages of at most 255 segments as needed (``comment_alone``: the setup header
    starts a page of its own); later pages are renumbered."""
    pages = ogg_pages(ogg)
    k = header_page_count(ogg)
    comment, setup = _split_packets(pages[1:k + 1])
    vendor = struct.unpack("<I", comment[7:11])[0]
    new = bytearray(comment[:11 + vendor]) + struct.pack("<I", len(comments))
    for text in comments:
        new += struct.pack("<I", len(text)) + text
    new += b"\x01"
    groups = [[bytes(new)], [setup]] if comment_alone else [[bytes(new), setup]]
    out = bytearray(ogg_page(*pages[0]))
    sequence = 1
    for group in groups:
        lacing = [v for packet in group
                  for v in [255] * (len(packet) // 255) + [len(packet) % 255]]
        body = b"".join(group)
        at = pos = 0
        while at < len(lacing):
            own = bytes(lacing[at:at + 255])
            flags = 1 if at > 0 and lacing[at - 1] == 255 else 0
            out += ogg_page(pages[1][0], own, body[pos:pos + sum(own)], sequence=sequence,
                            flags=flags)
            sequence += 1
            pos += sum(own)
            at += 255
    for fixed, lacing, body in pages[k + 1:]:
        out += ogg_page(fixed, lacing, body, sequence=sequence)
        sequence += 1
    return bytes(out)


@functools.cache
def intro_vorbis() -> bytes:
    """``loops/intro_vorbis.ogg``'s stand-in: house_lo.ogg at 48,000 Hz (78,331 frames)."""
    return with_rate(pygame_data("house_lo.ogg"), 48_000)


@functools.cache
def intro_opus() -> bytes:
    """``loops/intro_opus.opus``'s stand-in: house_lo.opus (341,036 frames at 48,000 Hz)."""
    return pygame_data("house_lo.opus")


@functools.cache
def existing_tags() -> bytes:
    """``intro_vorbis`` with ``LOOPSTART=1`` and ``LOOPLENGTH=1`` (and a title) already."""
    return with_comments(intro_vorbis(), [b"LOOPSTART=1", b"TITLE=house", b"LOOPLENGTH=1"])


@functools.cache
def long_72s() -> bytes:
    """78,331 samples declared at 1,087 Hz: 72.06 s (W28 reads ``1:12``)."""
    return with_rate(pygame_data("house_lo.ogg"), 1_087)


@functools.cache
def tagfull() -> bytes:
    """A ``PAD=`` comment sized so the comment packet fills page 1's segment table (255
    segments, the last one short) and the setup header starts page 2: adding the tags
    needs a page that isn't there."""
    base = intro_vorbis()
    comment = _split_packets(ogg_pages(base)[1:])[0]
    head = 11 + struct.unpack("<I", comment[7:11])[0]     # magic, vendor length, vendor
    size = 254 * 255 + 250                                # 255 segments, the last 250 bytes
    text = size - head - 4 - 4 - 1                        # count, its length, framing bit
    return with_comments(base, [b"PAD=" + b"x" * (text - 4)], comment_alone=True)


@functools.cache
def two_page_header() -> bytes:
    """A comment packet too big for one page: it continues on page 2, which has room."""
    return with_comments(intro_vorbis(), [b"PAD=" + b"y" * 70_000])


@functools.cache
def malformed() -> bytes:
    """``intro_vorbis`` with page 1's CRC flipped."""
    data = bytearray(intro_vorbis())
    at = sum(len(part) for part in ogg_pages(bytes(data))[0]) + 22
    data[at] ^= 0xFF
    return bytes(data)


# --- The example game ----------------------------------------------------------------------------

EXAMPLE_RATE = 22_050
EXAMPLE = ("bgm/lantern_walk.wav", "bgm/bridge_night.wav", "sfx/chime.wav", "sfx/river.wav",
           "sfx/firework.wav", "voice/hana_001.wav", "voice/hana_002.wav",
           "voice/daichi_001.wav", "blips/hana.wav", "blips/daichi.wav")
_PENTATONIC = (523.25, 587.33, 659.25, 783.99, 880.00, 1046.50)       # C5 D5 E5 G5 A5 C6
_MELODY = (0, 2, 4, 3, 2, 1, 2, 0, 1, 3, 5, 4, 3, 2, 1, 2)
_BASS = (130.81, 110.00, 174.61, 146.83)                               # C3 A2 F3 D3


def _render(notes: list[tuple[float, float, float, float]], seconds: float,
            rate: int, *, wrap: bool) -> list[float]:
    """Sum of decaying sines ``(start, freq, gain, decay_s)``; ``wrap``: tails continue
    from the start (a seamless loop)."""
    total = round(seconds * rate)
    buf = [0.0] * total
    for start, freq, gain, decay in notes:
        first = round(start * rate)
        length = round(decay * 5 * rate)
        step = 2 * math.pi * freq / rate
        attack = 0.006 * rate
        for i in range(length):
            at = first + i
            if at >= total:
                if not wrap:
                    break
                at %= total
            env = min(1.0, i / attack) * math.exp(-i / (decay * rate))
            buf[at] += gain * env * (math.sin(step * i) + 0.25 * math.sin(2 * step * i))
    return buf


def _to_pcm(buf: list[float], peak: float) -> bytes:
    top = max(1e-9, max(abs(v) for v in buf))
    return _pack([round(v / top * peak * FULL) for v in buf])


def example_music() -> bytes:
    """8.0 s at 120 BPM: a pentatonic melody in eighth notes over a soft bass, looping."""
    beat = 0.5
    notes = [(i * beat / 2 + 0.0, _PENTATONIC[n], 0.5, 0.35) for i, n in enumerate(_MELODY)]
    notes += [(i * beat / 2 + 4.0, _PENTATONIC[n] * (1.0 if i % 4 else 0.5), 0.45, 0.35)
              for i, n in enumerate(reversed(_MELODY))]
    notes += [(bar * 2.0, freq, 0.8, 0.9) for bar, freq in enumerate(_BASS)]
    return wav(_to_pcm(_render(notes, 8.0, EXAMPLE_RATE, wrap=True), 0.5), rate=EXAMPLE_RATE,
               channels=1)


def example_chime() -> bytes:
    """0.8 s: two bell partials, struck a fifth apart."""
    notes = [(0.0, 1318.5, 0.6, 0.18), (0.0, 1975.5, 0.3, 0.12), (0.06, 1975.5, 0.4, 0.15)]
    buf = _render(notes, 0.8, EXAMPLE_RATE, wrap=False)
    tail = round(0.05 * EXAMPLE_RATE)                    # fade the last 50 ms to silence
    for i in range(tail):
        buf[-tail + i] *= 1 - (i + 1) / tail
    return wav(_to_pcm(buf, 0.45), rate=EXAMPLE_RATE, channels=1)


def example_bridge_music() -> bytes:
    """8.0 s at 120 BPM, the bridge's song (step 12): an A minor pentatonic melody in quarter
    notes, slower and softer than the walk, over a held bass; looping like ``example_music``."""
    beat = 0.5
    notes = [(i * beat, _MINOR[n], 0.5, 0.55) for i, n in enumerate(_BRIDGE_MELODY)]
    notes += [(i * beat + beat / 2, _MINOR[n] * 2, 0.12, 0.25)            # a faint echo
              for i, n in enumerate(_BRIDGE_MELODY) if i % 2]
    notes += [(bar * 2.0, freq, 0.8, 1.2) for bar, freq in enumerate(_BRIDGE_BASS)]
    return wav(_to_pcm(_render(notes, 8.0, EXAMPLE_RATE, wrap=True), 0.45),
               rate=EXAMPLE_RATE, channels=1)


def _one_pole(buf: list[float], cutoff: float, rate: int, *, wrap: bool) -> list[float]:
    """A one-pole low-pass at ``cutoff`` Hz; ``wrap`` runs it twice around the buffer so
    its start continues from its end (a seamless loop)."""
    a = 1 - math.exp(-2 * math.pi * cutoff / rate)
    y = 0.0
    out = [0.0] * len(buf)
    for _ in range(2 if wrap else 1):
        for i, x in enumerate(buf):
            y += a * (x - y)
            out[i] = y
    return out


def example_river() -> bytes:
    """4.0 s of running water for ``play sound … loop`` (step 12): seeded noise, low-passed
    twice, with slow swells whose periods divide 4 s, so the loop has no seam."""
    total = round(4.0 * EXAMPLE_RATE)
    rng = random.Random(1201)
    noise = [rng.uniform(-1.0, 1.0) for _ in range(total)]
    low = _one_pole(_one_pole(noise, 700.0, EXAMPLE_RATE, wrap=True), 900.0, EXAMPLE_RATE,
                    wrap=True)
    burble = _one_pole(noise, 2_500.0, EXAMPLE_RATE, wrap=True)
    out = []
    for i in range(total):
        t = i / total
        swell = (0.75 + 0.15 * math.sin(2 * math.pi * 2 * t)
                 + 0.10 * math.sin(2 * math.pi * 5 * t + 1.0))
        out.append(swell * (low[i] + 0.15 * burble[i]
                            * (0.5 + 0.5 * math.sin(2 * math.pi * 11 * t))))
    return wav(_to_pcm(out, 0.5), rate=EXAMPLE_RATE, channels=1)


def example_firework() -> bytes:
    """2.0 s: a low thump that drops in pitch, a burst of noise, and crackles (step 12)."""
    total = round(2.0 * EXAMPLE_RATE)
    rng = random.Random(1202)
    buf = [0.0] * total
    phase = 0.0
    for i in range(total):
        t = i / EXAMPLE_RATE
        phase += 2 * math.pi * (45.0 + 70.0 * math.exp(-t / 0.08)) / EXAMPLE_RATE
        buf[i] = math.sin(phase) * min(1.0, t / 0.004) * math.exp(-t / 0.35)
    burst = _one_pole([rng.uniform(-1.0, 1.0) for _ in range(total)], 1_800.0, EXAMPLE_RATE,
                      wrap=False)
    for i in range(total):
        buf[i] += 1.4 * burst[i] * math.exp(-i / (0.25 * EXAMPLE_RATE))
    for _ in range(40):                                     # crackles, after the burst
        at = round(rng.uniform(0.35, 1.7) * EXAMPLE_RATE)
        gain = rng.uniform(0.15, 0.45) * math.exp(-(at / EXAMPLE_RATE - 0.35) / 0.6)
        for i in range(round(0.006 * EXAMPLE_RATE)):
            if at + i < total:
                buf[at + i] += gain * rng.uniform(-1.0, 1.0) * (1 - i / (0.006 * EXAMPLE_RATE))
    tail = round(0.1 * EXAMPLE_RATE)                        # fade the last 100 ms to silence
    for i in range(tail):
        buf[-tail + i] *= 1 - (i + 1) / tail
    return wav(_to_pcm(buf, 0.6), rate=EXAMPLE_RATE, channels=1)


def example_voice(syllables: str, *, f0: float, rise: float = 0.0, seed: int) -> bytes:
    """A voice-line stand-in that sounds like murmured speech (step 12): one vowel per
    letter of ``syllables`` (``a e i o u``; a space is a pause between words), each a pitched
    tone shaped by that vowel's formants, with a breathy onset. ``f0`` is the speaker's
    pitch; it falls over the line, and ``rise`` lifts its end, as a question or an
    exclamation does."""
    rng = random.Random(seed)
    syl_s, gap_s, word_s = 0.15, 0.025, 0.11
    events: list[tuple[float, str]] = []
    t = 0.12                                                # a breath before the first word
    for ch in syllables:
        if ch == " ":
            t += word_s
            continue
        events.append((t, ch))
        t += syl_s * rng.uniform(0.85, 1.25) + gap_s
    total = round((t + 0.2) * EXAMPLE_RATE)
    buf = [0.0] * total
    line_s = t
    for index, (start, vowel) in enumerate(events):
        length = round(syl_s * 1.15 * EXAMPLE_RATE)
        first = round(start * EXAMPLE_RATE)
        formants = _VOWELS[vowel]
        mean_f0 = f0 * (1.06 - 0.14 * start / line_s)
        top = int(3_400 / mean_f0)
        amps = []
        for h in range(1, top + 1):
            f = h * mean_f0
            gain = sum(a / (1 + ((f - fc) / bw) ** 2) for fc, bw, a in formants)
            amps.append(gain / h ** 0.6)
        phase = 0.0
        stress = 1.0 if index % 3 else 1.25
        for i in range(length):
            at = first + i
            if at >= total:
                break
            x = (start + i / EXAMPLE_RATE) / line_s
            pitch = f0 * (1.06 - 0.14 * x) * (1 + rise * max(0.0, x - 0.75) ** 2 * 16)
            pitch *= 1 + 0.01 * math.sin(2 * math.pi * 5.5 * i / EXAMPLE_RATE)
            phase += 2 * math.pi * pitch / EXAMPLE_RATE
            env = min(1.0, i / (0.02 * EXAMPLE_RATE)) * min(1.0, (length - i)
                                                             / (0.05 * EXAMPLE_RATE))
            value = sum(a * math.sin(h * phase) for h, a in enumerate(amps, start=1))
            if i < 0.012 * EXAMPLE_RATE:                    # a soft consonant
                value += 0.6 * rng.uniform(-1.0, 1.0)
            buf[at] += stress * env * value
    return wav(_to_pcm(_one_pole(buf, 4_000.0, EXAMPLE_RATE, wrap=False), 0.5),
               rate=EXAMPLE_RATE, channels=1)


def example_blip(freq: float, seconds: float, *, decay: float, overtone: float) -> bytes:
    """A text blip (F06 step 3): one short plucked tone at ``freq`` with an ``overtone``
    partial, faded to silence over its last 10 ms. A whole number of samples at 22,050 Hz,
    so its declared length is exact."""
    notes = [(0.0, freq, 1.0, decay), (0.0, freq * overtone, 0.35, decay * 0.6)]
    buf = _render(notes, seconds, EXAMPLE_RATE, wrap=False)
    tail = round(0.01 * EXAMPLE_RATE)
    for i in range(tail):
        buf[-tail + i] *= 1 - (i + 1) / tail
    return wav(_to_pcm(buf, 0.45), rate=EXAMPLE_RATE, channels=1)


# Formants (centre Hz, bandwidth Hz, gain) per vowel: a rough adult average.
_VOWELS = {
    "a": ((800, 90, 1.0), (1_200, 110, 0.6), (2_600, 160, 0.2)),
    "e": ((500, 80, 1.0), (1_800, 110, 0.5), (2_600, 160, 0.25)),
    "i": ((320, 70, 1.0), (2_300, 120, 0.45), (3_000, 170, 0.25)),
    "o": ((500, 80, 1.0), (900, 100, 0.6), (2_500, 160, 0.15)),
    "u": ((350, 70, 1.0), (800, 100, 0.4), (2_400, 160, 0.1)),
}
_MINOR = (440.00, 523.25, 587.33, 659.25, 783.99, 880.00)               # A4 C5 D5 E5 G5 A5
_BRIDGE_MELODY = (2, 1, 0, 1, 3, 2, 1, 2, 4, 3, 2, 3, 1, 0, 1, 0)
_BRIDGE_BASS = (110.00, 87.31, 130.81, 98.00)                          # A2 F2 C3 G2

# The example game's files, in ``EXAMPLE`` order (step 12 adds the bridge's song, the river,
# the firework, and three voice lines: "You came! I didn't think you would.", Daichi's
# question on the bridge, and "I can hear you, you know.").
EXAMPLE_BUILDERS = (
    example_music, example_bridge_music, example_chime, example_river, example_firework,
    lambda: example_voice("ue a ii i u u", f0=235.0, rise=0.35, seed=1),
    lambda: example_voice("a a i u u o", f0=230.0, rise=-0.1, seed=2),
    lambda: example_voice("e aiuo o a o a ai a i eii", f0=120.0, rise=0.05, seed=3),
    # F06: Hana's bright blip (C6, 0.06 s) and Daichi's low one (G3, 0.08 s).
    lambda: example_blip(1046.5, 0.06, decay=0.012, overtone=2.0),
    lambda: example_blip(196.0, 0.08, decay=0.02, overtone=3.0),
)
LICENSE_RECORD = "LICENSES.txt"


def license_record(files: dict[str, bytes]) -> str:
    """``audio/LICENSES.txt``: one entry per file (PR-F08-33, AC-F08-58), each with its
    license, author, how it was made, and its SHA-256 (``tests/audio/test_example_audio.py``
    checks each entry against its file)."""
    import hashlib

    lines = [
        "License records for the example game's audio (PR-F08-33).",
        "",
        "Every file in this folder is original: generated by tests/fixtures/F08/make_audio.py",
        "in the vn-engine repository (Python standard library only, fixed random seeds), by",
        "the vn-engine contributors, and dedicated to the public domain under CC0 1.0",
        "(https://creativecommons.org/publicdomain/zero/1.0/). Use them in your own game",
        "with no credit needed. To make them again:",
        "",
        "    .venv/Scripts/python tests/fixtures/F08/make_audio.py",
        "",
        "When you add audio of your own, add an entry for it here: who made it, where it",
        "came from, and its license.",
    ]
    for name, data in files.items():
        lines += ["", f"File: {name}", "License: CC0 1.0 (original)",
                  "Author: vn-engine contributors",
                  f"Source: {_SOURCES[name]}, tests/fixtures/F08/make_audio.py",
                  f"SHA-256: {hashlib.sha256(data).hexdigest()}"]
    return "\n".join(lines) + "\n"


_SOURCES = {
    "bgm/lantern_walk.wav": "example_music()",
    "bgm/bridge_night.wav": "example_bridge_music()",
    "sfx/chime.wav": "example_chime()",
    "sfx/river.wav": "example_river()",
    "sfx/firework.wav": "example_firework()",
    "voice/hana_001.wav": "example_voice(), murmured speech, not words",
    "voice/hana_002.wav": "example_voice(), murmured speech, not words",
    "voice/daichi_001.wav": "example_voice(), murmured speech, not words",
    "blips/hana.wav": "example_blip(), a text blip",
    "blips/daichi.wav": "example_blip(), a text blip",
}


def example_files() -> dict[str, bytes]:
    """``EXAMPLE``'s names -> their bytes."""
    return {name: build() for name, build in zip(EXAMPLE, EXAMPLE_BUILDERS, strict=True)}


def write_example(game: Path) -> list[Path]:
    """Write ``EXAMPLE`` and their license record into ``<game>/audio/`` (LF line ends)."""
    written = []
    files = example_files()
    for name, data in files.items():
        path = game / "audio" / name
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(data)
        written.append(path)
    record = game / "audio" / LICENSE_RECORD
    record.write_bytes(license_record(files).encode("utf-8"))
    written.append(record)
    return written


if __name__ == "__main__":
    folder = Path(sys.argv[1]) if len(sys.argv) > 1 else GAME
    for path in write_example(folder):
        print(f"{path} ({path.stat().st_size:,} bytes)")
